select coalesce(json_agg(json_build_object('table',c.relname,'name',con.conname,'type',con.contype,'definition',pg_get_constraintdef(con.oid),'deferrable',con.condeferrable,'validated',con.convalidated) order by c.relname,con.conname),'[]'::json) as data from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public';
